effect.shader:
// Wobble Rail Streaks - AM single pass, GLES-safe

float rand21(vec2 c){ return fract(sin(dot(c, vec2(12.9898,78.233))) * 43758.5453); }

void main(){
    vec2 R = acScreenSize;
    vec2 frag = acScreenNorm * R;
    vec2 p = (2.0 * frag - R) / min(R.x, R.y) * UV_SCALE;

    float z0 = acTime * SPEED;
    float i = floor(z0);
    float offs = fract(z0);
    float shadow = 1.0;

    vec3 outc = vec3(0.0);

    int maxSteps = int(clamp(STEPS, 1.0, 300.0));
    const int MAX_IT = 300;
    for (int zi = 1; zi < MAX_IT; zi++){
        if (zi >= maxSteps) break;
        float z = float(zi);
        float z2 = z - offs;
        float randz = z + i;

        float dadt = (rand21(vec2(randz, 1.0)) * 2.0 - 1.0) * 0.5;
        float a = rand21(vec2(randz, 1.0)) * 2.0 * 3.14159265 + dadt * acTime;
        float pullback = rand21(vec2(randz, 3.0)) * PULL_ADD + PULL_MIN;
        float r = rand21(vec2(randz, 4.0)) * R_ADD + R_MIN;
        float g = rand21(vec2(randz, 5.0)) * G_ADD + G_MIN;
        float b = rand21(vec2(randz, 6.0)) * B_ADD + B_MIN;

        vec2 origin = vec2(sin(randz*0.005)+sin(randz*0.002), cos(randz*0.005)+cos(randz*0.002)) * z2 * 0.002;
        vec2 dir = vec2(cos(a), sin(a));
        float dist = dot(dir, p - origin) * z2;
        float xdist = dot(vec2(-dir.y, dir.x), p - origin) * z2;
        float wobble = dist - pullback + sin(xdist * WOBBLE_FREQ) * WOBBLE_AMP;

        if (wobble > 0.0){
            float dotsize = rand21(vec2(randz, 7.0)) * DOT_ADD + DOT_MIN;
            float patternsize = rand21(vec2(randz, 8.0)) * PAT_ADD + PAT_MIN;
            float pattern = step(dotsize, length(fract(vec2(dist, xdist) * patternsize) - 0.5)) * PAT_GAIN + PAT_BASE;

            float bright = 1.0;
            if (wobble < THRESH_1) bright = BRIGHT_1;
            else if (wobble < THRESH_2) bright = BRIGHT_2;
            else bright = pattern;

            vec3 col = vec3(r, g, b);
            vec3 cacc = GAIN * col * shadow / (z2 + DENOM_BIAS) * bright;
            outc = cacc;
            outc = pow(max(outc, 0.0), vec3(GAMMA));
            gl_FragColor = vec4(outc, 1.0);
            return;
        } else {
            shadow *= 1.0 - exp((dist - pullback) * SHADOW_DECAY) * SHADOW_GAIN;
        }
    }

    gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
}
